/** Statistical validation of one replayed Frontier decision certificate. */
@Experimental
public final class PackedFrontierDecisionValidator {

	private static final double MASS_TOLERANCE = 1.0e-9d;

	private PackedFrontierDecisionValidator() {
	}

	/**
	 * Validates every same-tier competitor as a paired candidate-margin confidence sequence.
	 *
	 * <p>
	 * A tuple is paired as the complete ordered Frontier tuple plus its complete bound-mask stratum. Tuple columns are
	 * never projected into independent scalar sets. Detached residual weights are already Horvitz--Thompson adjusted,
	 * so this method deliberately uses {@link FrontierPairedCostSequence#observeAdjusted(double, double, boolean)}.
	 */
	public static Result validate(PackedPlanValidationRequest request, PackedCostingReplay.Result replay,
			int decision, int selectedCandidate, int familyComparisonCount, double confidence,
			double posteriorExpectedRegret,
			double maximumExpectedRegret) {
		Objects.requireNonNull(request, "request");
		Objects.requireNonNull(replay, "replay");
		if (decision < 0 || decision >= request.decisionCount()
				|| selectedCandidate < request.decisionStart(decision)
				|| selectedCandidate >= request.decisionEnd(decision)) {
			return Result.declined("selected-candidate-outside-certificate");
		}
		if (familyComparisonCount <= 0) {
			throw new IllegalArgumentException("paired comparison family must be positive");
		}
		if (!probability(confidence)) {
			throw new IllegalArgumentException("Frontier validation confidence must be in (0, 1)");
		}
		if (!Double.isFinite(maximumExpectedRegret)
				|| maximumExpectedRegret < 0.0d
				|| maximumExpectedRegret > 1.0d) {
			throw new IllegalArgumentException("Frontier expected-regret limit must be in [0, 1]");
		}
		if (!Double.isFinite(posteriorExpectedRegret)
				|| posteriorExpectedRegret < 0.0d
				|| posteriorExpectedRegret > 1.0d) {
			throw new IllegalArgumentException("Frontier posterior expected regret must be in [0, 1]");
		}
		if (posteriorExpectedRegret > maximumExpectedRegret) {
			return Result.declined("paired-decision-regret-budget-exceeded");
		}

		int selectedTier = request.candidateTier(selectedCandidate);
		int comparisonCount = 0;
		for (int candidate = request.decisionStart(decision); candidate < request.decisionEnd(decision); candidate++) {
			if (candidate != selectedCandidate && request.candidateTier(candidate) == selectedTier) {
				comparisonCount++;
			}
		}
		if (comparisonCount == 0) {
			return Result.certified(
					confidence, posteriorExpectedRegret, 0, "paired-cost-events-certified");
		}

		FrontierEvidenceBundle cached = request.evidenceBundle();
		FrontierEvidenceBundle current = replay.currentEvidence();
		CandidateEvidence cachedSelected = candidateEvidence(
				cached, request.candidateStateOrdinal(selectedCandidate), request.candidateCost(selectedCandidate));
		CandidateEvidence currentSelected = candidateEvidence(
				current,
				replay.currentStateOrdinal(request.candidateStateOrdinal(selectedCandidate)),
				replay.candidateCost(selectedCandidate));
		if (cachedSelected == null || currentSelected == null) {
			return Result.declined("selected-candidate-has-no-pairable-inline-evidence");
		}
		if (!sameSamplingDesign(cachedSelected.key, currentSelected.key)) {
			return Result.declined("selected-candidate-sampling-design-changed");
		}

		int observations = 0;
		for (int candidate = request.decisionStart(decision); candidate < request.decisionEnd(decision); candidate++) {
			if (candidate == selectedCandidate || request.candidateTier(candidate) != selectedTier) {
				continue;
			}
			CandidateEvidence cachedAlternative = candidateEvidence(
					cached, request.candidateStateOrdinal(candidate), request.candidateCost(candidate));
			CandidateEvidence currentAlternative = candidateEvidence(
					current,
					replay.currentStateOrdinal(request.candidateStateOrdinal(candidate)),
					replay.candidateCost(candidate));
			if (cachedAlternative == null || currentAlternative == null) {
				return Result.declined("competing-candidate-has-no-pairable-inline-evidence");
			}
			if (!compatiblePairing(cachedSelected, cachedAlternative)
					|| !compatiblePairing(currentSelected, currentAlternative)
					|| !sameSamplingDesign(cachedAlternative.key, currentAlternative.key)) {
				return Result.declined("candidate-pairing-design-incompatible");
			}

			Comparison comparison = compare(
					cachedSelected, cachedAlternative, currentSelected, currentAlternative,
					confidence, familyComparisonCount);
			if (!comparison.certified) {
				return Result.declined(comparison.reason);
			}
			observations = Math.addExact(observations, comparison.observations);
		}
		return Result.certified(
				confidence, posteriorExpectedRegret, observations, "paired-cost-events-certified");
	}

	private static Comparison compare(CandidateEvidence cachedSelected, CandidateEvidence cachedAlternative,
			CandidateEvidence currentSelected, CandidateEvidence currentAlternative,
			double confidence, int familyCount) {
		Set<TupleIdentity> identities = new HashSet<>();
		identities.addAll(cachedSelected.contributions.keySet());
		identities.addAll(cachedAlternative.contributions.keySet());
		identities.addAll(currentSelected.contributions.keySet());
		identities.addAll(currentAlternative.contributions.keySet());
		if (identities.isEmpty()) {
			double oldMargin = cachedAlternative.cost - cachedSelected.cost;
			double currentMargin = currentAlternative.cost - currentSelected.cost;
			return oldMargin >= 0.0d && currentMargin >= 0.0d
					? Comparison.certified(0, 0.0d)
					: Comparison.declined("empty-evidence-does-not-certify-candidate-margin");
		}

		double contributionBound = contributionBound(cachedSelected)
				+ contributionBound(cachedAlternative)
				+ contributionBound(currentSelected)
				+ contributionBound(currentAlternative);
		if (!Double.isFinite(contributionBound) || contributionBound <= 0.0d) {
			return Comparison.declined("candidate-contribution-bound-unavailable");
		}
		FrontierPairedCostSequence sequence = new FrontierPairedCostSequence(
				confidence, familyCount, Math.nextUp(contributionBound));
		double reconstructedOldMargin = 0.0d;
		double reconstructedCurrentMargin = 0.0d;
		for (TupleIdentity identity : identities) {
			Contribution oldSelected = cachedSelected.contributions.get(identity);
			Contribution oldAlternative = cachedAlternative.contributions.get(identity);
			Contribution newSelected = currentSelected.contributions.get(identity);
			Contribution newAlternative = currentAlternative.contributions.get(identity);
			double oldMarginContribution = value(oldAlternative) - value(oldSelected);
			double currentMarginContribution = value(newAlternative) - value(newSelected);
			boolean exact = exactOrAbsent(oldSelected, cachedSelected)
					&& exactOrAbsent(oldAlternative, cachedAlternative)
					&& exactOrAbsent(newSelected, currentSelected)
					&& exactOrAbsent(newAlternative, currentAlternative);
			sequence.observeAdjusted(oldMarginContribution, currentMarginContribution, exact);
			reconstructedOldMargin += oldMarginContribution;
			reconstructedCurrentMargin += currentMarginContribution;
		}

		double oldMargin = cachedAlternative.cost - cachedSelected.cost;
		double currentMargin = currentAlternative.cost - currentSelected.cost;
		if (!sameAggregate(reconstructedOldMargin, oldMargin)
				|| !sameAggregate(reconstructedCurrentMargin, currentMargin)) {
			return Comparison.declined("candidate-contributions-do-not-reconstruct-cost-event");
		}
		FrontierPairedCostSequence.Snapshot snapshot = sequence.snapshot();
		double lowerCurrentMargin = oldMargin / identities.size() + snapshot.lowerBound();
		if (!(lowerCurrentMargin >= 0.0d)) {
			return Comparison.declined("paired-candidate-margin-not-certified");
		}
		return Comparison.certified(identities.size(), 0.0d);
	}

	private static CandidateEvidence candidateEvidence(FrontierEvidenceBundle bundle, int ordinal, double cost) {
		if (ordinal <= 0
				|| !finiteNonNegative(cost)
				|| bundle.payloadKind(ordinal) != FrontierEvidenceBundle.PayloadKind.INLINE
				|| bundle.disposition(ordinal) != FrontierStateDisposition.COMPOSABLE_PAYLOAD) {
			return null;
		}
		EvidenceGuarantee guarantee = bundle.guarantee(ordinal);
		if (guarantee != EvidenceGuarantee.DATABASE_EXACT
				&& guarantee != EvidenceGuarantee.MEASURE_UNBIASED) {
			return null;
		}
		EvidenceStateSummary summary = bundle.summary(ordinal);
		double pointRows = summary.pointRows();
		if (pointRows == 0.0d) {
			return cost == 0.0d
					? new CandidateEvidence(bundle.key(ordinal), bundle.layout(ordinal), bundle.masks(ordinal), summary,
							cost, Map.of(), guarantee == EvidenceGuarantee.DATABASE_EXACT)
					: null;
		}
		if (!(pointRows > 0.0d) || !Double.isFinite(pointRows)) {
			return null;
		}
		FrontierMaskStrata masks = bundle.masks(ordinal);
		if (masks == null || !masks.layout().equals(bundle.layout(ordinal))) {
			return null;
		}
		Map<TupleIdentity, Contribution> contributions = new HashMap<>();
		double scale = cost / pointRows;
		double payloadMass = 0.0d;
		for (int stratum = 0; stratum < masks.stratumCount(); stratum++) {
			for (int index = 0; index < bundle.exactCount(ordinal, stratum); index++) {
				double weight = bundle.exactWeight(ordinal, stratum, index);
				payloadMass += weight;
				merge(contributions, tuple(bundle, ordinal, stratum, index, true), weight * scale, true);
			}
			for (int index = 0; index < bundle.residualCount(ordinal, stratum); index++) {
				double weight = bundle.residualWeight(ordinal, stratum, index);
				payloadMass += weight;
				merge(contributions, tuple(bundle, ordinal, stratum, index, false), weight * scale, false);
			}
		}
		if (!sameAggregate(payloadMass, pointRows)) {
			return null;
		}
		return new CandidateEvidence(bundle.key(ordinal), bundle.layout(ordinal), masks, summary, cost,
				contributions, guarantee == EvidenceGuarantee.DATABASE_EXACT);
	}

	private static TupleIdentity tuple(FrontierEvidenceBundle bundle, int ordinal, int stratum, int index,
			boolean exact) {
		FrontierMaskStrata masks = bundle.masks(ordinal);
		long[] maskWords = new long[masks.wordCount()];
		for (int word = 0; word < maskWords.length; word++) {
			maskWords[word] = masks.word(stratum, word);
		}
		long[] terms = new long[bundle.layout(ordinal).size()];
		for (int slot = 0; slot < terms.length; slot++) {
			terms[slot] = exact
					? bundle.exactTermId(ordinal, stratum, index, slot)
					: bundle.residualTermId(ordinal, stratum, index, slot);
		}
		return new TupleIdentity(maskWords, terms);
	}

	private static void merge(Map<TupleIdentity, Contribution> contributions, TupleIdentity identity,
			double value, boolean exact) {
		Contribution prior = contributions.get(identity);
		if (prior == null) {
			contributions.put(identity, new Contribution(value, exact));
		} else {
			contributions.put(identity, new Contribution(prior.value + value, prior.exact && exact));
		}
	}

	private static boolean compatiblePairing(CandidateEvidence left, CandidateEvidence right) {
		return left.layout.equals(right.layout)
				&& left.masks.equals(right.masks)
				&& sameSamplingDesign(left.key, right.key);
	}

	private static boolean sameSamplingDesign(FrontierStateKey left, FrontierStateKey right) {
		if (left == null || right == null
				|| !left.frontier().equals(right.frontier())
				|| !left.maskStrata().equals(right.maskStrata())
				|| left.semanticScope() != right.semanticScope()
				|| left.correlationScope() != right.correlationScope()
				|| left.continuationObjective() != right.continuationObjective()
				|| left.snapshotStoreIdHigh() != right.snapshotStoreIdHigh()
				|| left.snapshotStoreIdLow() != right.snapshotStoreIdLow()
				|| left.laneFamily() != right.laneFamily()
				|| left.laneIndex() != right.laneIndex()
				|| left.seedVersion() != right.seedVersion()
				|| left.logicalFactorWordCount() != right.logicalFactorWordCount()) {
			return false;
		}
		for (int word = 0; word < left.logicalFactorWordCount(); word++) {
			if (left.logicalFactorWord(word) != right.logicalFactorWord(word)) {
				return false;
			}
		}
		return true;
	}

	private static double contributionBound(CandidateEvidence evidence) {
		if (evidence.databaseExact || evidence.cost == 0.0d) {
			return 0.0d;
		}
		double fraction = evidence.summary.maximumWeightFraction();
		if (!Double.isFinite(fraction) || fraction <= 0.0d || fraction > 1.0d) {
			return Double.NaN;
		}
		return evidence.cost * fraction;
	}

	private static boolean exactOrAbsent(Contribution contribution, CandidateEvidence evidence) {
		return contribution == null ? evidence.databaseExact : contribution.exact;
	}

	private static double value(Contribution contribution) {
		return contribution == null ? 0.0d : contribution.value;
	}

	private static boolean sameAggregate(double left, double right) {
		double scale = Math.max(1.0d, Math.max(Math.abs(left), Math.abs(right)));
		return Math.abs(left - right) <= MASS_TOLERANCE * scale;
	}

	private static boolean finiteNonNegative(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	private static boolean probability(double value) {
		return Double.isFinite(value) && value > 0.0d && value < 1.0d;
	}

	/** Result of paired decision validation without any store-owned state. */
	@Experimental
	public record Result(boolean certified, double confidence, double expectedRegret, int observations,
			String reason) {

		private static Result certified(double confidence, double expectedRegret, int observations, String reason) {
			return new Result(true, confidence, expectedRegret, observations, reason);
		}

		private static Result declined(String reason) {
			return new Result(false, 0.0d, 1.0d, 0, reason);
		}
	}

	private record CandidateEvidence(FrontierStateKey key, FrontierLayout layout, FrontierMaskStrata masks,
			EvidenceStateSummary summary, double cost, Map<TupleIdentity, Contribution> contributions,
			boolean databaseExact) {
	}

	private record Contribution(double value, boolean exact) {
	}

	private static final class TupleIdentity {

		private final long[] maskWords;
		private final long[] terms;
		private final int hash;

		private TupleIdentity(long[] maskWords, long[] terms) {
			this.maskWords = maskWords;
			this.terms = terms;
			hash = 31 * Arrays.hashCode(maskWords) + Arrays.hashCode(terms);
		}

		@Override
		public boolean equals(Object other) {
			return this == other
					|| other instanceof TupleIdentity identity
							&& Arrays.equals(maskWords, identity.maskWords)
							&& Arrays.equals(terms, identity.terms);
		}

		@Override
		public int hashCode() {
			return hash;
		}
	}

	private record Comparison(boolean certified, int observations, double expectedRegret, String reason) {

		private static Comparison certified(int observations, double expectedRegret) {
			return new Comparison(true, observations, expectedRegret, "");
		}

		private static Comparison declined(String reason) {
			return new Comparison(false, 0, 1.0d, reason);
		}
	}
}
